                stu(cp, r[i][0]);
                stu(cp + VW, r[i][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int i = 0; i < MR; i++) {
            memcpy(&tmp[i][0], &r[i][0], sizeof(vf));
            memcpy(&tmp[i][VW], &r[i][1], sizeof(vf));
