static job_t g_job;

static void barrier_wait(job_t *j)
{
    int g = __atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE);
    if (__atomic_add_fetch(&j->bar_count, 1, __ATOMIC_ACQ_REL) == j->nt) {
        __atomic_store_n(&j->bar_count, 0, __ATOMIC_RELAXED);
        __atomic_store_n(&j->bar_gen, g + 1, __ATOMIC_RELEASE);
    } else {
        long spins = 0;
        while (__atomic_load_n(&j->bar_gen, __ATOMIC_ACQUIRE) == g) {
            cpu_relax();
            if (++spins > (1 << 16)) { sched_yield(); spins = 0; }
        }
    }
}

static void compute_tile(job_t *j, int t)
{
    int n = j->n, Mp = j->Mp, Np = j->Np;
    int ti = t / j->tiles_n, tj = t % j->tiles_n;
    int i0 = ti * j->tile_m, i1 = i0 + j->tile_m;
    int j0 = tj * j->tile_n, j1 = j0 + j->tile_n;
    if (i1 > n) i1 = n;
    if (j1 > n) j1 = n;
    float *C = j->C;

    for (int pc = 0; pc < n; pc += KC) {
        int kc = n - pc < KC ? n - pc : KC;
        int acc = pc != 0;
        const float *ab = j->Ap + (size_t)pc * Mp;
        const float *bb = j->Bp + (size_t)pc * Np;
        for (int jr = j0; jr < j1; jr += NR) {
            int nr = j1 - jr < NR ? j1 - jr : NR;
            const float *bp = bb + (size_t)jr * kc;
            for (int ir = i0; ir < i1; ir += MR) {
                int mr = i1 - ir < MR ? i1 - ir : MR;
                kernel(kc, ab + (size_t)ir * kc, bp, C + (size_t)ir * n + jr, n, mr, nr, acc);
            }
        }
    }
}

static void run(job_t *j, int tid)
{
    int nt = j->nt, n = j->n;

    int npa = j->Mp / MR;
    int pa0 = (int)((long)npa * tid / nt), pa1 = (int)((long)npa * (tid + 1) / nt);
    for (int p = pa0; p < pa1; p++)
        pack_a_panel(j->A, n, j->Mp, p * MR, j->Ap);

    int k0 = (int)((long)n * tid / nt), k1 = (int)((long)n * (tid + 1) / nt);
    pack_b_rows(j->B, n, j->Np, k0, k1, j->Bp);

    if (nt > 1) {
        barrier_wait(j);
        for (;;) {
            int t = __atomic_fetch_add(&j->next, 1, __ATOMIC_RELAXED);
            if (t >= j->ntiles) break;
            compute_tile(j, t);
        }
    } else {
        for (int t = 0; t < j->ntiles; t++) compute_tile(j, t);
    }
}

/* Persistent pool. */
static pthread_mutex_t g_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_cv = PTHREAD_COND_INITIALIZER;
static unsigned g_gen;
static int g_remaining;
static int g_pool = -1;
static int g_hw = 1;

static void *pool_main(void *arg)
{
    int tid = (int)(long)arg;
    unsigned seen = 0;
    for (;;) {
        unsigned g;
        long spins = 0;
        while ((g = __atomic_load_n(&g_gen, __ATOMIC_ACQUIRE)) == seen) {
            if (++spins < SPIN_LIMIT) {
                cpu_relax();
