}

static void pool_init(void)
{
    g_hw = detect_threads();
    int created = 0;
    for (int t = 1; t < g_hw; t++) {
        pthread_t th;
        if (pthread_create(&th, NULL, pool_main, (void *)(long)t) != 0) break;
        pthread_detach(th);
        created++;
