static void choose_tiles(int n, int nt, int *tm, int *tn)
{
    double best = 1e300;
    int bm = 96, bn = 256;
    for (int m = 48; m <= 120; m += MR) {
        for (int w = 4 * NR > 64 ? 4 * NR : 64; w <= 512; w += NR) {
            long tiles = (long)((n + m - 1) / m) * ((n + w - 1) / w);
            long rounds = (tiles + nt - 1) / nt;
            double cost = (double)rounds * m * w * (1.0 + 12.0 / m + 12.0 / w);
            if (cost < best) { best = cost; bm = m; bn = w; }
        }
    }
    *tm = bm;
    *tn = bn;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    if (g_pool < 0) pool_init();

    int Mp = (n + MR - 1) / MR * MR;
    int Np = (n + NR - 1) / NR * NR;
    float *Ap = ensure(&g_Abuf, &g_Acap, (size_t)Mp * n);
    float *Bp = ensure(&g_Bbuf, &g_Bcap, (size_t)Np * n);
    if (!Ap || !Bp) { naive(A, B, C, n); return; }

    int nt = g_pool + 1;
    if (n < 96) nt = 1;

    int tm, tn;
    if (nt > 1) {
        choose_tiles(n, nt, &tm, &tn);
    } else {
        tm = 96;
        tn = 256;
    }
    int tiles_m = (n + tm - 1) / tm, tiles_n = (n + tn - 1) / tn;
    int ntiles = tiles_m * tiles_n;
    if (nt > ntiles) nt = ntiles;
    if (nt < 1) nt = 1;

    job_t *j = &g_job;
    j->A = A; j->B = B; j->C = C; j->Ap = Ap; j->Bp = Bp;
    j->n = n; j->Mp = Mp; j->Np = Np; j->nt = nt;
    j->tile_m = tm; j->tile_n = tn; j->tiles_n = tiles_n; j->ntiles = ntiles;
    j->next = 0;
    j->bar_count = 0;

    if (nt == 1) {
        run(j, 0);
        return;
    }

    __atomic_store_n(&g_remaining, g_pool, __ATOMIC_RELEASE);
    pthread_mutex_lock(&g_mu);
    __atomic_add_fetch(&g_gen, 1, __ATOMIC_ACQ_REL);
    pthread_cond_broadcast(&g_cv);
    pthread_mutex_unlock(&g_mu);

    run(j, 0);

    while (__atomic_load_n(&g_remaining, __ATOMIC_ACQUIRE) != 0)
        cpu_relax();
}
